    "legal.currentBadge": "Активные документы",
    "legal.dataManagementBody": "Пользователи могут удалять локальные данные: профиль, контакты, настройки и юридические согласия. Полный сброс удаляет локальные данные, управляемые AGM.",
    "legal.dataManagementInstructions": "Выберите, какие локальные данные вы хотите удалить. Это влияет только на данные, сохранённые AGM на этом устройстве.",
    "legal.dataManagementTitle": "Управление данными",
    "legal.dataSafetyBody": "Введённые данные могут включать текст, сообщения и контактные данные. Данные, передаваемые для перевода, должны быть указаны в Google Play Data Safety в соответствии с активными функциями.",
    "legal.dataSafetyTitle": "Google Play Data Safety",
    "legal.deleteAcceptance": "Удалить согласия",
    "legal.deleteContacts": "Удалить контакты",
    "legal.deleteOcrHistory": "Удалить историю OCR",
    "legal.deletePreferences": "Удалить настройки",
    "legal.deleteProfile": "Удалить профиль",
    "legal.description": "Юридический центр для Политики конфиденциальности, Условий, прозрачности ИИ, использования микрофона, управления данными и информации о приложении.",
    "legal.firstRunBody": "Чтобы использовать функции передачи текста для перевода или использовать микрофон, подтвердите, что вы прочитали Политику конфиденциальности, Условия, уведомление об ИИ и уведомление о микрофоне.",
    "legal.firstRunTitle": "Юридическая информация перед использованием",
