    "legal.impressumBody": "Для публикации в Германии на публичной странице приложения должны быть указаны данные разработчика, адрес и электронный контакт в соответствии с применимыми требованиями.",
    "legal.impressumTitle": "Импрессум / Данные разработчика",
    "legal.licenseCapacitorBody": "Capacitor используется для упаковки веб-приложения в Android-приложение. Точная лицензия должна сохраняться в соответствии с установленным пакетом.",
    "legal.licenseCapacitorTitle": "Capacitor",
    "legal.licenseTesseractBody": "Tesseract.js используется для локального распознавания текста с изображений в функции Camera OCR.",
    "legal.licenseTesseractTitle": "Tesseract.js",
    "legal.licenseTypescriptBody": "TypeScript используется для проверки и компиляции кода фронтенда. Точная лицензия должна сохраняться в соответствии с установленным пакетом.",
    "legal.licenseTypescriptTitle": "TypeScript",
    "legal.licenseViteBody": "Vite используется для сборки фронтенда. Точная лицензия должна сохраняться в соответствии с установленным пакетом.",
    "legal.licenseViteTitle": "Vite",
    "legal.licensesBody": "Приложение использует технологии с открытым исходным кодом и сторонние сервисы. Лицензии и уведомления доступны на специальной странице.",
    "legal.licensesIntro": "Уведомления для основных компонентов с открытым исходным кодом и технических провайдеров, используемых приложением.",
    "legal.licensesTitle": "Лицензии с открытым исходным кодом / Уведомления третьих сторон",
    "legal.microphoneBody": "Микрофон активируется только когда пользователь начинает диктовку. Голос используется для распознавания речи и вставки транскрипта в текстовое поле.",
    "legal.microphoneTitle": "Использование микрофона",
    "legal.moduleName": "Юридическая информация и соответствие требованиям",
    "legal.privacyBody": "Данные профиля, вручную введённые контакты, подписи, предпочтения и согласия хранятся локально на устройстве. Текст передаётся вне устройства только по запросу пользователя для перевода через доступный сервис.",
    "legal.privacyTitle": "Политика конфиденциальности",
    "legal.resetAllLocalData": "Сбросить все локальные данные",
    "legal.reviewDocuments": "Просмотреть документы",
